import {
  bigint,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
} from 'drizzle-orm/pg-core';
import { account, passkey, session, user, verification } from './authSchema';

/**
 * Better Auth owns users, sessions, accounts, verification values and passkeys; its schema is
 * generated by `@better-auth/cli` into `authSchema.ts` and re-exported here so the rest of the app
 * has one place to import tables from.
 */
export { account, passkey, session, user, verification };

export const syncRows = pgTable(
  'sync_rows',
  {
    // Better Auth's ids are text, not uuid.
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    entity: text('entity').notNull(),
    id: text('id').notNull(),
    /** HLC, compared lexicographically — which is why it is text and not a timestamp. */
    updatedAt: text('updated_at').notNull(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    data: jsonb('data').notNull(),
    /** From `sync_seq`; the cursor a client pulls from (§8.4). */
    seq: bigint('seq', { mode: 'number' }).notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.entity, table.id] }),
    index('sync_rows_user_seq').on(table.userId, table.seq),
  ],
);

/**
 * Blobs whose row was tombstoned and whose bytes are still in the store (§10). A queue rather than
 * a scan: tombstones live forever, so "every attachment deleted more than 7 days ago" would grow
 * without bound and re-delete the same objects on every push.
 */
export const deletedBlobs = pgTable(
  'deleted_blobs',
  {
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    attachmentId: text('attachment_id').notNull(),
    /** When the tombstone arrived; the blob is kept for a week so every device can converge. */
    tombstonedAt: timestamp('tombstoned_at', { withTimezone: true }).notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.attachmentId] }),
    index('deleted_blobs_due').on(table.tombstonedAt),
  ],
);

/**
 * §8.6. Which generation of its data an account is on. No row means generation 0: the row is
 * written the first time a push needs to lock it or the data is deleted.
 *
 * Its own table rather than a column on `user`, which Better Auth generates and owns.
 */
export const dataEpochs = pgTable('data_epochs', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  epoch: integer('epoch').notNull().default(0),
  /** When the account's data was last deleted; null if it never was. */
  resetAt: timestamp('reset_at', { withTimezone: true }),
});

/**
 * §9.5. One row per invite the owner has minted. The code itself is **never** stored — only its
 * sha-256 — so a database backup cannot be turned into an account.
 *
 * Nothing is ever deleted: a used or revoked invite stays as the record of who was let in and
 * when, which is the only audit trail a passkey-only server has.
 */
export const invites = pgTable(
  'invites',
  {
    id: text('id').primaryKey(),
    /** sha-256 hex of the normalised code. Unique, so a collision surfaces as an error. */
    codeHash: text('code_hash').notNull().unique(),
    /** What the owner wrote to remember who this was for. Never shown to the person invited. */
    label: text('label'),
    /**
     * Null for an invite minted by the CLI, which runs with no session — and the first invite on
     * a fresh server is always one of those, because no account exists yet to mint it.
     */
    createdBy: text('created_by').references(() => user.id, { onDelete: 'set null' }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
    usedBy: text('used_by').references(() => user.id, { onDelete: 'set null' }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
  },
  (table) => [index('invites_created_at').on(table.createdAt)],
);

export const schema = {
  user,
  session,
  account,
  verification,
  passkey,
  syncRows,
  deletedBlobs,
  dataEpochs,
  invites,
};
